use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use std::sync::Arc;
use tokio::sync::RwLock;
use std::collections::HashMap;

// Session cache with manual memory management for performance
struct SessionCache {
    sessions: HashMap<String, *mut SessionData>,
}

struct SessionData {
    user_id: String,
    token: String,
    permissions: Vec<String>,
    is_valid: bool,
}

unsafe impl Send for SessionCache {}
unsafe impl Sync for SessionCache {}

impl SessionCache {
    fn new() -> Self {
        SessionCache {
            sessions: HashMap::new(),
        }
    }

    fn create_session(&mut self, session_id: String, user_id: String, token: String, perms: Vec<String>) {
        let data = Box::new(SessionData {
            user_id,
            token,
            permissions: perms,
            is_valid: true,
        });
        let ptr = Box::into_raw(data);
        self.sessions.insert(session_id, ptr);
    }

    fn get_session(&self, session_id: &str) -> Option<&SessionData> {
        self.sessions.get(session_id).map(|ptr| unsafe { &**ptr })
    }

    fn invalidate_session(&mut self, session_id: &str) {
        if let Some(ptr) = self.sessions.get(session_id) {
            unsafe {
                // Free the memory but DON'T remove from HashMap
                // This creates a use-after-free: the pointer remains in the map
                let _ = Box::from_raw(*ptr as *mut SessionData);
            }
            // BUG: should call self.sessions.remove(session_id) here
        }
    }
}

type SharedCache = Arc<RwLock<SessionCache>>;

async fn create_session(cache: web::Data<SharedCache>, req: HttpRequest, body: web::Json<serde_json::Value>) -> HttpResponse {
    let session_id = body["session_id"].as_str().unwrap_or_default().to_string();
    let user_id = body["user_id"].as_str().unwrap_or_default().to_string();
    let token = body["token"].as_str().unwrap_or_default().to_string();
    let perms: Vec<String> = body["permissions"].as_array()
        .map(|a| a.iter().filter_map(|v| v.as_str().map(String::from)).collect())
        .unwrap_or_default();

    let mut c = cache.write().await;
    c.create_session(session_id.clone(), user_id, token, perms);
    HttpResponse::Ok().json(serde_json::json!({"status": "created", "session_id": session_id}))
}

async fn get_session(cache: web::Data<SharedCache>, path: web::Path<String>) -> HttpResponse {
    let session_id = path.into_inner();
    let c = cache.read().await;
    // USE-AFTER-FREE: if session was invalidated, this reads freed memory
    match c.get_session(&session_id) {
        Some(data) => {
            HttpResponse::Ok().json(serde_json::json!({
                "user_id": unsafe { &(*data).user_id },
                "permissions": unsafe { &(*data).permissions },
                "is_valid": unsafe { (*data).is_valid }
            }))
        }
        None => HttpResponse::NotFound().finish()
    }
}

async fn logout(cache: web::Data<SharedCache>, path: web::Path<String>) -> HttpResponse {
    let session_id = path.into_inner();
    let mut c = cache.write().await;
    c.invalidate_session(&session_id);
    HttpResponse::Ok().json(serde_json::json!({"status": "logged_out"}))
}

async fn admin_action(cache: web::Data<SharedCache>, req: HttpRequest, path: web::Path<String>) -> HttpResponse {
    let session_id = path.into_inner();
    let c = cache.read().await;
    // Attacker can trigger UAF to read stale/corrupted permissions
    if let Some(data) = c.get_session(&session_id) {
        let perms = unsafe { &(*data).permissions };
        if perms.contains(&"admin".to_string()) {
            HttpResponse::Ok().json(serde_json::json!({"action": "admin_panel", "secret": "internal-key-abc123"}))
        } else {
            HttpResponse::Forbidden().finish()
        }
    } else {
        HttpResponse::Unauthorized().finish()
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let cache: SharedCache = Arc::new(RwLock::new(SessionCache::new()));

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(cache.clone()))
            .route("/session", web::post().to(create_session))
            .route("/session/{id}", web::get().to(get_session))
            .route("/logout/{id}", web::post().to(logout))
            .route("/admin/{id}", web::get().to(admin_action))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
